Type Date = Enregistrement
Debut
    jour : Entier;
    mois[12] : Chaine;
    annee : Entier;
Fin;

Algorithme DemoEnregistrementSimple;
Var
    d1, d2 : Date;
Debut
    // Affectation champ par champ via la notation pointée
    d1.jour := 26;
    d1.mois := "Février";
    d1.annee := 2026;

    // Affichage des champs
    Ecrire("Date saisie : ", d1.jour, " ", d1.mois, " ", d1.annee);
Fin.

Type Date = Enregistrement
Debut
    jour, mois, annee : Entier;
Fin;

Algorithme ComparaisonEnregistrements;
Var
    d1, d2 : Date;
Debut
    d1.jour := 15; d1.mois := 8; d1.annee := 2026;
    d2 := d1; // Affectation globale (d2 reçoit la même copie)

    // Comparaison champ par champ obligatoire
    Si (d1.jour = d2.jour Et d1.mois = d2.mois Et d1.annee = d2.annee) Alors
        Ecrire("Les deux dates sont identiques !");
    Sinon
        Ecrire("Les deux dates sont différentes.");
    Fin Si;
Fin.

Type Date = Enregistrement
Debut
    jour, mois, annee : Entier;
Fin;

Type Adresse = Enregistrement
Debut
    rue, commune, wilaya[30] : Chaine;
Fin;

Type Personne = Enregistrement
Debut
    nom, prenom[25] : Chaine;
    naissance : Date;   // Enregistrement imbriqué
    adr : Adresse;      // Enregistrement imbriqué
Fin;

Algorithme EnregistrementsImbriques;
Var
    P : Personne;
Debut
    P.nom := "HOSNI";
    P.prenom := "Amine";
    P.naissance.jour := 26;
    P.naissance.mois := 2;
    P.naissance.annee := 2006;
    P.adr.commune := "Annaba";
    P.adr.wilaya := "Annaba";

    Ecrire("Nom : ", P.nom, " Né le : ", P.naissance.jour, "/", P.naissance.mois, "/", P.naissance.annee);
Fin.

Type Etudiant = Enregistrement
Debut
    nom[25] : Chaine;
    moyenne : Reel;
Fin;

Algorithme TableauEnregistrements;
Var
    Promotion[100] : Etudiant;
    N, i : Entier;
Debut
    N := 3;
    Promotion[1].nom := "Ali"; Promotion[1].moyenne := 14.5;
    Promotion[2].nom := "Sara"; Promotion[2].moyenne := 16.0;
    Promotion[3].nom := "Omar"; Promotion[3].moyenne := 9.5;

    Ecrire("--- Liste des Admis (Moyenne >= 10) ---");
    Pour i := 1 a N Faire
        Si (Promotion[i].moyenne >= 10.0) Alors
            Ecrire(Promotion[i].nom, " - Moyenne : ", Promotion[i].moyenne);
        Fin Si;
    Fin Pour;
Fin.
